@Transactional
public List<FundsHold> place(UUID accountId, List<String> walletCodes) {
    var account = account.accountOrLastKnown(accountId);
    for (var label : walletCodes)
        if (!account.hasWallet(label)) throw new UnknownWalletException(accountId, label);

    var holds = repository.saveAll(...);

    // same transaction. either both rows exist or neither does.
    outbox.append(EventEnvelope.of("ledger.FundsHeld",
            holds.getFirst().id(), 1, MDC.get("requestId"), null,
            new FundsHeld(...)));

    return holds;
}

package io.ledgerflow.ledger.adapter.out.persistence;

import tools.jackson.databind.ObjectMapper;
import io.ledgerflow.events.EventEnvelope;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Component;

@Component
public class OutboxAppender {

    private final JdbcClient db;
    private final ObjectMapper json;

    OutboxAppender(JdbcClient db, ObjectMapper json) { this.db = db; this.json = json; }

    /** Must be called inside the caller's transaction - no @Transactional here. */
    public void append(EventEnvelope<?> e) {
        db.sql("""
               INSERT INTO outbox (id, aggregate_type, aggregate_id, event_type,
                                   payload, headers, occurred_at)
               VALUES (?, ?, ?, ?, ?::jsonb, ?::jsonb, ?)
               """)
          .params(e.eventId(), "wallet-hold", e.aggregateId().toString(), e.eventType(),
                  write(e.payload()), write(headers(e)), e.occurredAt())
          .update();
    }
}

package io.ledgerflow.ledger.adapter.out.messaging;

import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Component
class OutboxPublisher {

    private static final String CLAIM = """
            SELECT id, aggregate_id, event_type, payload, headers
              FROM outbox
             WHERE published_at IS NULL
             ORDER BY occurred_at
             LIMIT 100
             FOR UPDATE SKIP LOCKED
            """;

    private final JdbcClient db;
    private final KafkaTemplate<String, Object> kafka;

    OutboxPublisher(JdbcClient db, KafkaTemplate<String, Object> kafka) {
        this.db = db; this.kafka = kafka;
    }

    @Scheduled(fixedDelay = 500)
    @Transactional
    void drain() {
        var batch = db.sql(CLAIM).query(OutboxRow.class).list();
        for (var row : batch) {
            kafka.send("ledgerflow.ledger.wallet-hold.events.v1", row.aggregateId(), row.payload());
            db.sql("UPDATE outbox SET published_at = now() WHERE id = ?")
              .param(row.id()).update();
        }
    }

    record OutboxRow(UUID id, String aggregateId, String eventType, String payload, String headers) {}
}
